import{_ as t,o as a,c as o,a2 as r}from"./chunks/framework.iWwp2X7T.js";const h=JSON.parse('{"title":"Troubleshooting","description":"Mobile Inspector development documentation · Troubleshooting","frontmatter":{"title":"Troubleshooting","description":"Mobile Inspector development documentation · Troubleshooting"},"headers":[],"relativePath":"en/troubleshooting/index.md","filePath":"en/troubleshooting/index.md"}'),n={name:"en/troubleshooting/index.md"};function i(d,e,s,c,l,p){return a(),o("div",null,[...e[0]||(e[0]=[r('<h1 id="troubleshooting" tabindex="-1">Troubleshooting <a class="header-anchor" href="#troubleshooting" aria-label="Permalink to &quot;Troubleshooting&quot;">​</a></h1><p>Start with <code>--version</code> and <code>doctor --json</code>. Record the selected version, home, command and fixed error code. Keep credentials, pairing JSON and private capture bodies out of support messages.</p><table tabindex="0"><thead><tr><th>Symptom</th><th>Check and next action</th></tr></thead><tbody><tr><td>Private clone denied</td><td>Verify authorized repository access; public docs do not grant it</td></tr><tr><td>Owner conflict or stale state</td><td>Inspect ownership; choose a separate owned home, never kill an arbitrary PID</td></tr><tr><td>Phone QR unavailable</td><td>Select a routable LAN address; loopback is local-only</td></tr><tr><td>Camera denied</td><td>Use manual pairing; request camera only after a new Scan action</td></tr><tr><td>Configured, no events</td><td>Start recording explicitly; verify actual transport and destination</td></tr><tr><td>Browser/WeChat/Harmony TLS fails</td><td>Supply system-trusted HTTPS; check legal domains/origin policy</td></tr><tr><td>Trace has gaps</td><td>Check bounds/sequence/completeness; do not claim a full capture</td></tr><tr><td>MCP stale cursor</td><td>List again deliberately in the same project; never reuse another generation</td></tr><tr><td>Codex diagnosis rejected</td><td><code>UNSUPPORTED_SANDBOX</code> is current admission, not a setting to bypass</td></tr></tbody></table><h2 id="separate-causes" tabindex="-1">Separate causes <a class="header-anchor" href="#separate-causes" aria-label="Permalink to &quot;Separate causes&quot;">​</a></h2><p>A 503 is an HTTP observation, not proof of client code failure. A cancelled request may be expected. Missing source mapping means provenance is incomplete. Check <a href="./../reference/incidents">incident semantics</a> before assigning cause.</p><p>For USB, validate physical trust/cable/Xcode discovery before pairing. For export, inspect explicit log text even when bodies are excluded. On account/environment changes clear/disconnect; old callbacks should be invalidated. If a device behavior is uncertain, report it as unverified rather than replacing actual receipt with browser or unit-test evidence.</p>',6)])])}const b=t(n,[["render",i]]);export{h as __pageData,b as default};
